import type { UsageDetail, UsageSource } from "./contracts";
import type { LinkMeasurement, TransferCounts } from "./measurements";
import { count, text } from "./validation";

const counters = () => ({ offeredBytes: 0n, acceptedBytes: 0n, rejectedBytes: 0n, deliveredBytes: 0n, failedBytes: 0n, liveBytes: 0n, offeredTransfers: 0n, terminalTransfers: 0n, liveTransfers: 0n });
type Counters = ReturnType<typeof counters>;
const serialized = (c: Counters): TransferCounts => Object.fromEntries(Object.entries(c).map(([k, v]) => [k, String(v)])) as TransferCounts;
type Direction = "request" | "response" | "unattributed";
export class LinkMeter {
  private totals = counters();
  private directions = { request: counters(), response: counters(), unattributed: counters() };
  private live = new Map<number, { bytes: bigint; accepted: boolean; direction: Direction }>();
  constructor(readonly source: Extract<UsageSource, { family: "link" }>) {}
  apply(detail: UsageDetail) {
    if (detail.kind === "transfer-start") {
      if (count(detail.transfer) !== this.totals.offeredTransfers + 1n || this.live.has(detail.transfer) || typeof detail.accepted !== "boolean") throw Error("Transfer identity sequence gap/duplicate");
      text(detail.id); const bytes = count(detail.bytes), context = detail.context;
      let direction: Direction = "unattributed";
      if (context !== null) {
        if (!["request", "response"].includes(context.direction)) throw Error("Unknown transfer direction");
        text(context.path, 160); text(context.origin, 160); text(context.destination, 160); text(context.callId); text(context.rootId); count(context.hop);
        if (count(context.attempt) < 1n) throw Error("Missing transfer attempt identity");
        direction = context.direction;
      }
      this.live.set(detail.transfer, { bytes, accepted: detail.accepted, direction });
      for (const c of [this.totals, this.directions[direction]]) {
        c.offeredTransfers++; c.liveTransfers++; c.offeredBytes += bytes;
        if (detail.accepted) { c.acceptedBytes += bytes; c.liveBytes += bytes; } else c.rejectedBytes += bytes;
      }
      return;
    }
    if (detail.kind !== "transfer-end") throw Error("Wrong transfer usage dimension");
    const transfer = this.live.get(detail.transfer);
    if (!transfer || !["delivered", "unreachable", "overflow", "aborted"].includes(detail.outcome) || !transfer.accepted && !["unreachable", "overflow"].includes(detail.outcome) || transfer.accepted && detail.outcome === "overflow") throw Error("Transfer terminal has no matching admission");
    this.live.delete(detail.transfer);
    for (const c of [this.totals, this.directions[transfer.direction]]) {
      c.terminalTransfers++; c.liveTransfers--;
      if (transfer.accepted) {
        c.liveBytes -= transfer.bytes;
        if (detail.outcome === "delivered") c.deliveredBytes += transfer.bytes; else c.failedBytes += transfer.bytes;
      }
    }
  }
  snapshot(): LinkMeasurement {
    return { family: "link", resource: this.source.resource, from: this.source.from, to: this.source.to, totals: serialized(this.totals),
      directions: { request: serialized(this.directions.request), response: serialized(this.directions.response), unattributed: serialized(this.directions.unattributed) }, providerBillableTransfer: "Unknown" };
  }
}

import type { StoredObject, UsageDetail } from "./contracts";
import type { ObjectMeasurement, OperationCounts } from "./measurements";
import { count, objectKey, objectRow, text } from "./validation";

const counters = () => ({ received: 0n, admitted: 0n, completed: 0n, failed: 0n, rejected: 0n, cancelled: 0n });
type Counters = ReturnType<typeof counters>;
const counts = (c: Counters): OperationCounts => ({ received: String(c.received), completed: String(c.completed), failed: String(c.failed), rejected: String(c.rejected), cancelled: String(c.cancelled), admitted: String(c.admitted), live: String(c.received - c.completed - c.failed - c.rejected - c.cancelled) });
export class ObjectMeter {
  private origin = false;
  private objects = new Map<string, StoredObject>();
  private requests = new Map<number, { command: string | null; admitted: boolean; changed: boolean }>();
  private commands = new Map<string, { command: string | null; totals: Counters }>();
  private totals = counters();
  private bytes = 0n;
  private area = 0n;
  private lastAt = 0;
  private generation = 0;
  private puts = 0n;
  private replaced = 0n;
  private removed = 0n;
  private createdBytes = 0n;
  private releasedBytes = 0n;
  constructor(readonly resource: string) {}
  apply(detail: UsageDetail, at: number) {
    count(at);
    if (at < this.lastAt) throw Error("Late object event cannot rewrite an issued time sequence");
    this.area += this.bytes * BigInt(at - this.lastAt); this.lastAt = at;
    if (detail.kind === "object-origin") {
      if (this.origin || this.totals.received || at !== 0) throw Error("Object origin is missing, repeated or not at run origin");
      this.origin = true;
      for (const value of detail.objects) { const row = objectRow(value), key = objectKey(row); if (this.objects.has(key)) throw Error("Duplicate initial object"); this.objects.set(key, row); this.bytes += BigInt(row.bytes); this.generation = Math.max(this.generation, row.generation); }
      return;
    }
    if (!this.origin) throw Error("Object origin missing");
    if (detail.kind === "operation-start") {
      if (count(detail.request) !== this.totals.received + 1n || this.requests.has(detail.request) || typeof detail.admitted !== "boolean") throw Error("Request receipt sequence gap/duplicate");
      text(detail.callId); text(detail.rootId); if (count(detail.attempt) < 1n) throw Error("Request attempt identity missing");
      if (detail.command !== null) text(detail.command);
      const key = JSON.stringify(detail.command), command = this.commands.get(key) ?? { command: detail.command, totals: counters() };
      this.commands.set(key, command); this.requests.set(detail.request, { command: detail.command, admitted: detail.admitted, changed: false }); this.totals.received++; command.totals.received++;
      if (detail.admitted) { this.totals.admitted++; command.totals.admitted++; }
      return;
    }
    if (detail.kind === "operation-end") {
      const request = this.requests.get(detail.request);
      if (!request || !["completed", "failed", "rejected", "cancelled"].includes(detail.outcome) || detail.reason !== null && typeof detail.reason !== "string") throw Error("Unmatched request terminal");
      if ((detail.outcome === "rejected") === request.admitted) throw Error("Request admission and terminal disagree");
      if (detail.reason !== null) text(detail.reason);
      if (request.changed && detail.outcome !== "completed") throw Error("Object commit and service terminal disagree");
      this.requests.delete(detail.request); this.totals[detail.outcome]++; this.commands.get(JSON.stringify(request.command))!.totals[detail.outcome]++;
      return;
    }
    if (detail.kind !== "object-mutation") throw Error("Wrong object usage dimension");
    const request = this.requests.get(detail.request);
    if (!request || !request.admitted || request.changed || request.command !== detail.command || !["put", "delete"].includes(detail.command)) throw Error("Mutation has no matching live request");
    const before = detail.before ? objectRow(detail.before) : null, after = detail.after ? objectRow(detail.after) : null, identity = after ?? before;
    if (!identity || before && after && objectKey(before) !== objectKey(after)) throw Error("Mutation identity mismatch");
    const key = objectKey(identity), previous = this.objects.get(key) ?? null;
    if (JSON.stringify(previous) !== JSON.stringify(before)) throw Error("Missing mutation or mismatched prior generation/bytes");
    if (detail.command === "put") {
      if (!after || after.generation !== this.generation + 1) throw Error("Put generation is not the next actual store generation");
      this.generation = after.generation; this.objects.set(key, after); this.puts++; if (before) this.replaced++;
    } else {
      if (!before || after) throw Error("Delete must remove an actual current object");
      this.objects.delete(key); this.removed++;
    }
    this.createdBytes += BigInt(after?.bytes ?? 0); this.releasedBytes += BigInt(before?.bytes ?? 0);
    this.bytes += BigInt(after?.bytes ?? 0) - BigInt(before?.bytes ?? 0); request.changed = true;
  }
  snapshot(at: number): ObjectMeasurement {
    count(at); if (!this.origin || at < this.lastAt) throw Error("Object observation is incomplete or precedes its history");
    return { family: "object-store", resource: this.resource, storedBytes: String(this.bytes), byteUs: String(this.area + this.bytes * BigInt(at - this.lastAt)), generation: this.generation,
      objects: [...this.objects.values()].sort((a, b) => objectKey(a) < objectKey(b) ? -1 : 1).map((r) => ({ ...r })), committedPuts: String(this.puts), replacedObjects: String(this.replaced), removedObjects: String(this.removed), createdBytes: String(this.createdBytes), releasedBytes: String(this.releasedBytes), operations: counts(this.totals),
      commands: [...this.commands.values()].sort((a, b) => JSON.stringify(a.command) < JSON.stringify(b.command) ? -1 : 1).map((c) => ({ command: c.command, counts: counts(c.totals) })) };
  }
}

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { meteringFixture } from "../../packages/simulation/tests/meteringFixture";
import { providerHasher } from "../../packages/simulation/tests/providerFixture";
import { createMeteredProviderModel2 } from "../../packages/simulation/src/reality/metering/run";
import { createProviderModel2 } from "../../packages/simulation/src/reality/provider/run";
import { usageWindow } from "../../packages/simulation/src/reality/metering/windows";
import { combineUsageWindows } from "../../packages/simulation/src/reality/metering/combine";
import { replayUsage } from "../../packages/simulation/src/reality/metering/replay";
import { historicalFoundationHash, historicalProviderHash, verifyHistoricalArtifacts } from "./source-lineage";
import { meteringArtifactBytes, meteringDigest, meteringRoot, meteringSourceHash } from "./metering-source";

export function meteringProofs() {
  verifyHistoricalArtifacts();
  const base = meteringFixture(), variants = [
    { name: "normal", options: {} }, { name: "capacity-rejection", options: { capacity: true } },
    { name: "response-loss-after-commit", options: { responseLoss: true } }, { name: "process-retention", options: { outage: true } },
    { name: "collector-overflow", options: { maxRecords: 1 } }
  ];
  const cases = variants.map(({ name, options }) => {
    const f = meteringFixture(options), runtime = createMeteredProviderModel2(f.compiled, f.config, providerHasher), plain = createProviderModel2(f.compiled, providerHasher);
    const cuts = [runtime.evidence().usage];
    for (let i = 1; i <= 32; i++) { runtime.advanceTo(i * runtime.horizon / 32); cuts.push(runtime.evidence().usage); }
    plain.advanceTo(plain.horizon);
    const final = runtime.evidence(), reference = plain.evidence(), frame = runtime.frame(), window = usageWindow(cuts[0]!, cuts.at(-1)!, providerHasher);
    if (final.model.capture.failure || meteringDigest(final.model) !== meteringDigest(reference.model) || meteringDigest(final.provider) !== meteringDigest(reference.provider) || final.provider.total.kind !== "Unknown") throw Error(`Usage altered actual model/provider execution: ${name}`);
    if (options.maxRecords) {
      if (final.usage.complete || frame.records.length !== 1 || window.kind !== "Unknown") throw Error("Retention overflow did not fail closed");
    } else {
      if (!final.usage.complete || window.kind !== "Observed" || !replayUsage(frame, providerHasher).matches) throw Error(`Incomplete real usage proof: ${name}`);
      const parts = cuts.slice(1).map((cut, i) => usageWindow(cuts[i]!, cut, providerHasher));
      if (meteringDigest(combineUsageWindows(parts, providerHasher)) !== meteringDigest(window)) throw Error(`Window recombination failed: ${name}`);
      if (combineUsageWindows([window, window], providerHasher).kind !== "Unknown") throw Error("Repeated windows became additive");
    }
    return { name, options, compiled: f.compiled.fingerprint, model: meteringDigest(final.model), provider: meteringDigest(final.provider), cuts: cuts.map((c) => ({ atUs: c.atUs, fingerprint: c.fingerprint, complete: c.complete })), window, frame };
  });
  return { schema: "infraforge-usage-proofs/1", complete: true, sourceHash: meteringSourceHash(), historicalFoundation: historicalFoundationHash(), historicalProvider: historicalProviderHash(),
    authoredBase: { design: base.design, contract: base.contract, provider: base.provider, config: base.config }, cases,
    scope: "Observed authored simulated object state, service attempts and directed payload only. Provider storage/request/transfer billing and full bill Unknown.",
    omitted: "Each variant is reconstructed from retained authored base plus source-pinned fixture options. Routine model traces and duplicate cumulative frames are omitted; one replayable source-event frame per variant is retained." };
}
export function validateMeteringProofs() {
  const retained = JSON.parse(readFileSync(resolve(meteringRoot, "docs/reality/m2j-proofs.json"), "utf8")), actual = meteringProofs();
  if (meteringDigest(retained) !== meteringDigest(actual)) throw Error("M2J current source, authored input or actual evidence drift");
  if (meteringArtifactBytes() > 1048576) throw Error("M2J proof/lineage/measurement review budget exceeded");
  return { cases: actual.cases.length, cuts: actual.cases.reduce((n, c) => n + c.cuts.length, 0), records: actual.cases.reduce((n, c) => n + c.frame.records.length, 0), artifactBytes: meteringArtifactBytes(), sourceHash: actual.sourceHash };
}
if (import.meta.main) {
  if (process.argv.includes("--write")) writeFileSync(resolve(meteringRoot, "docs/reality/m2j-proofs.json"), JSON.stringify(meteringProofs()) + "\n");
  console.info(JSON.stringify(validateMeteringProofs()));
}

import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { validateMeteringProofs } from "../reality/metering-proofs";
import { meteringArtifactBytes, meteringRoot, meteringSourceHash } from "../reality/metering-source";
import { readLineage, sourceProjection, historicalFoundationHash, historicalProviderHash } from "../reality/source-lineage";

test("M2J source-pinned actual product usage and all 165 cuts replay within the shared retention budget", () => {
  expect(validateMeteringProofs()).toMatchObject({ cases: 5, cuts: 165 });
  expect(meteringArtifactBytes()).toBeLessThanOrEqual(1048576);
}, 30000);
test("M2J current executor measurements retain actual source identity and bounded overflow", () => {
  const p = JSON.parse(readFileSync(resolve(meteringRoot, "docs/reality/m2j-performance.json"), "utf8"));
  expect(p.sourceHash).toBe(meteringSourceHash()); expect(p.complete).toBe(true);
  for (const key of ["compileMs", "setupMs", "runMs", "captureMs", "frameMs", "serializeMs", "replayMs"]) expect(p[key]).toBeGreaterThanOrEqual(0);
  expect(p.overflow.complete).toBe(false); expect(p.overflow.retained.records).toBe(1); expect(p.scope).toContain("not provider physical timing");
});
test("accepted source projection rejects changed originals, changed current source and unapproved mappings", () => {
  const lineage = readLineage(), read = (p: string) => readFileSync(resolve(meteringRoot, p), "utf8");
  expect(historicalFoundationHash()).toBe(lineage.foundationHash); expect(historicalProviderHash()).toBe(lineage.providerHash);
  const original = structuredClone(lineage); original.files[0]!.originalText += "\n// drift";
  expect(() => sourceProjection(original, read)).toThrow("drift");
  expect(() => sourceProjection(lineage, (p) => read(p) + "\n// drift")).toThrow("drift");
  const unapproved = structuredClone(lineage); unapproved.files[0]!.path = "unknown.ts";
  expect(() => sourceProjection(unapproved, read)).toThrow("drift");
});

import type { NumericSite } from "./scan";
import type { RealityEntry } from "../../packages/simulation/src/reality/ledger";
import type { Unit } from "../../packages/simulation/src/reality/quantity";

export const AUDIT_SHA = "361a3b1afe33740d8f45d9c79601c6476657d602";
export function classify(site: NumericSite): RealityEntry {
  const { file, symbol, context } = site;
  let classification: RealityEntry["classification"] = "implementation-policy", unit: Unit = "code-number";
  let scope = "Application bookkeeping, presentation or operational guard; not infrastructure physics";
  let assumptions = ["This literal is not evidence of real infrastructure capacity or performance."];
  let replacement = "Retain as an implementation policy; separate from modeled infrastructure measurements.";
  if (/packages\/simulation\//.test(file)) {
    classification = "educational-assumption"; scope = "Published Model-1 engine behavior";
    assumptions = ["Fixed educational coefficients; no application benchmark or provider measurement establishes a universal value."];
    replacement = "M2: explicit service demand, capacity, queues and resource-specific state; require provenance or Unknown.";
    if (/capacity\.ts/.test(file)) unit = "requests/s";
    if (/cost\.ts/.test(file)) { classification = "approximation"; unit = symbol.includes("MONTHLY") ? "USD/month" : "code-number";
      replacement = "M2G: dated provider/region tariffs, billing units, minimums and explicit missing cost components."; }
    if (/DURATION|SECONDS|TICKS/.test(symbol)) unit = "seconds";
    if (/RPS_PER|QPS_PER/.test(symbol)) unit = "mixed";
    if (/DEGRADED_AT|SATURATED_AT|TARGET_CPU|SCALE_DOWN_AT|CPU_SPIKE_BOOST/.test(symbol)) unit = "percent";
    if (/CACHE_HIT_RATIO|FACTOR|MULTIPLIER|AMPLIFICATION|MAX_RETRY_BOOST/.test(symbol)) unit = "ratio";
    if (/MAX_LOAD_FRACTION|MAX_EFFECTIVE_LOAD|VM_WRITE_CPU_TAX/.test(symbol)) unit = "ratio";
    if (/PAYLOAD_KB/.test(symbol)) unit = "kB-label";
    if (/BANDWIDTH_CAPACITY_KBPS/.test(symbol)) unit = "kB/s";
    if (/MEMORY_LEAK_RATE|KBPS_PER_GBPS/.test(symbol)) unit = "mixed";
    if (/DB_POOL_PER|MAX_DB_CONNECTIONS|DEFAULT_MAX_CAP/.test(symbol)) unit = "count";
    if (/SPAWN_Y_GAP|spawnOrigin/.test(symbol)) { classification = "implementation-policy"; unit = "code-number"; scope = "Canvas layout, not physics"; }
    if (/engineHelpers/.test(file) && /mulberry32|round1/.test(symbol)) { classification = "implementation-policy"; unit = "code-number"; scope = "Replay RNG/rounding algorithm, not a measured stochastic process"; }
    if (/targetRps/.test(symbol) && [60, 3600].includes(site.value)) { classification = "derived"; unit = "seconds"; assumptions = ["Exact minute/hour conversion; workload rate itself is selected configuration."]; replacement = "Retain explicit unit conversions in M2."; }
    if (/engineRouting/.test(file)) { classification = "derived"; assumptions = ["Graph traversal, equal splitting and fixed read/miss/write fractions; no request completion, queue or path latency is calculated."]; }
    if ([0, 1].includes(site.value) && /length|\[0\]|Counter|hotTicks|coldTicks|inDegree|remainingTicks|const remaining|let monthlyTotal|let (cpu|stress|boost)|processed/.test(context)) {
      classification = "implementation-policy"; unit = "code-number"; scope = "Initialization, indexing, count arithmetic or discrete tick lifecycle";
    }
  } else if (/packages\/catalog\/src\/.+catalog\.ts/.test(file)) {
    scope = "Historical provider-labelled catalog snapshot 2026-08; field validity is independent";
    classification = /monthlyPriceUsd|maxConnections|networkGbps/.test(symbol) ? "approximation" : "unverified";
    unit = symbol.endsWith("vCpu") ? "cores" : symbol.endsWith("ramGb") ? "GB-label" : symbol.endsWith("monthlyPriceUsd") ? "USD/month" : symbol.endsWith("networkGbps") ? "Gbps" : symbol.endsWith("maxConnections") ? "count" : "ratio";
    assumptions = ["Repository snapshot is implementation provenance only; provider identity does not verify this exact field.", "No region/date/credit-mode/guaranteed-versus-burst contract is captured per field."];
    replacement = "M2G: verify each SKU field independently against a dated provider specification; separate limits, estimates and tariff terms.";
    if (symbol.startsWith("AWS_COMPUTE.") && symbol.endsWith("baselineFactor") && /baselineFactor: 0\.(40|60)/.test(context) && /t3\.(medium|large)/.test(context)) {
      classification = "obsolete"; assumptions.push("Published T3 per-vCPU baseline is 20% for medium and 30% for large; Model 1 stores 40%/60%. Preserve historical behavior.");
    }
  } else if (/workload|DeployDialog/.test(file)) {
    classification = "educational-assumption"; scope = "Selectable example workload/default or workload validation bound";
    assumptions = ["A preset becomes captured configuration when selected; it is not observed production demand."];
    replacement = "M2B: request classes and measured/configured service-demand profiles, explicit arrival model and assumptions.";
  } else if (/challenges\/definitions|challenges\/starter/.test(file)) {
    classification = "calibrated-model"; scope = "Immutable educational scenario, calibrated against Model 1 only";
    assumptions = ["Passing/failing engine fixtures establish educational behavior, not real cloud accuracy."];
    replacement = "Keep V1 immutable. Later M2K publishes newly calibrated Model-2 challenge versions.";
  } else if (/evidence|experimentTrace|challenges\/validate|comparison|reports/.test(file)) {
    classification = "implementation-policy"; scope = "Evidence retention, authoring, comparison or report presentation guard";
    assumptions = ["Bounds govern what can be claimed, not infrastructure capacity. Missing evidence remains unknown."];
    replacement = "Keep existing historical report semantics; design separate versioned M2 evidence with units/provenance.";
  } else if (/example|preset/i.test(file)) {
    classification = "educational-assumption"; scope = "Example architecture/configuration, including nonphysical layout coordinates";
    replacement = "Label examples as configuration; never infer provider capacity from layout or resource count alone.";
  } else if (/RESOURCE_PORTS|securityScan|CONNECTION_RULES|validation/.test(file)) {
    scope = "Default protocol ports, topology/readiness rules or limited static security checks";
    assumptions = ["Defaults are configurable conventions; static checks do not simulate firewalls, TLS or prove security."];
    replacement = "M2: explicit listener/protocol/reachability and security policy; retain static warnings separately.";
    if (/RESOURCE_PORTS|openPorts/.test(file + context)) unit = "port";
  }
  const evidence: RealityEntry["provenance"] = [{ source: `repo:${AUDIT_SHA}/${file}#L${site.line}`, supports: "implementation", detail: "Exact historical literal and source expression; not external validation." }];
  if (file === "apps/backend/stages/costEstimation.stages.ts" && context.includes("GENERIC_MONTHLY_USD") && site.value === 10) {
    classification = "approximation"; unit = "USD/month"; scope = "Historical fallback price in deployment-time cost estimation";
    assumptions = ["Fallback estimate, not a documented provider tariff; runtime cost.ts contains the matching historical fallback."];
    replacement = "M2G: missing tariff remains Unknown; derive priced components from dated provider/service/region billing rules.";
  }
  if (classification === "obsolete") evidence.push({ source: "https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-credits-baseline-concepts.html", supports: "qualitative",
    detail: "Contradicts this stored coefficient: EC2 t3.medium/large baselines are 20%/30% per vCPU. Exact replacement facts are separately recorded in provider-facts.json; this source does not validate the stored value." });
  if (file.includes("apps/web/src/features/monitoring/store/") && /metrics|cpu|health|loadFraction|simulatedSeconds|burnRate|accumulatedCost/.test(symbol + context)) {
    classification = "placeholder"; scope = "Client initial/missing-snapshot defaults, not an infrastructure measurement";
    assumptions = ["Zero/initial values can be UI state without retained measurements; they do not establish measured zero usage."];
    replacement = "M2 evidence/UI must keep missing or stale measurements explicit; use Unknown instead of numeric substitution.";
  }
  if (classification === "calibrated-model") evidence.push({ source: "apps/backend/tests/challengeHarness.ts", supports: "exact", detail: "Deterministic starter/reference tests support scenario outcomes only, not physical accuracy." });
  if (classification === "implementation-policy") assumptions.push("Permitted only as nonphysical bookkeeping, UI or an explicit implementation guard; never an infrastructure performance claim.");
  return { id: site.id, concept: `${symbol || file.split("/").at(-1)} · literal ${site.text}`, modelVersion: "1", scope,
    quantity: { kind: "known", value: site.value, unit, provenance: [site.id] }, formula: context,
    classification, confidence: classification === "implementation-policy" ? "high" : classification === "calibrated-model" ? "conditional" : "low",
    provenance: evidence, assumptions, researchedOn: "2026-10-15", freeMode: classification === "implementation-policy" ? "conditional" : "forbidden", replacement };
}

import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { buildInventory, root } from "../reality/inventory";
import { scanFile } from "../reality/scan";
import { classify } from "../reality/classify";
import { validateLedger } from "../../packages/simulation/src/reality/ledger";
import { requireKnown, sumQuantities, validateQuantity } from "../../packages/simulation/src/reality/quantity";
import { validateArtifacts, validateDepth } from "../reality/artifacts";
import ignore from "ignore";

test("every production numeric literal and source file is inventoried; implementation is not provider provenance", () => {
  const actual = buildInventory();
  expect(JSON.parse(readFileSync(resolve(root, "docs/reality/model1-ledger.json"), "utf8"))).toEqual(actual);
  expect(actual.ledger.length).toBeGreaterThan(2000); expect(actual.files.length).toBeGreaterThan(350);
  for (const file of ["apps/backend/lib/prisma.ts", "apps/web/src/lib/format.ts", "apps/web/src/lib/useMediaQuery.ts"])
    expect(actual.files.some((entry) => entry.file === file)).toBe(true);
  expect(validateLedger(actual.ledger)).toEqual([]);
  expect(actual.ledger.find((e) => e.location.file === "apps/backend/stages/costEstimation.stages.ts" && e.formula.includes("GENERIC_MONTHLY_USD")))
    .toMatchObject({ classification: "approximation", freeMode: "forbidden", quantity: { unit: "USD/month", value: 10 } });
  expect(actual.ledger.filter((e) => e.classification === "obsolete").length).toBe(2);
  expect(actual.ledger.filter((e) => e.classification !== "implementation-policy").every((e) => e.freeMode === "forbidden")).toBe(true);
});
test("scanner includes inline constants and negative/unit conversion literals without parsing comments as physics", () => {
  const sites = scanFile("packages/simulation/src/test.ts", "// 123\nconst x = -2.5 * 1_000; const y = 0x10;");
  expect(sites.map((s) => s.value)).toEqual([-2.5, 1000, 16]);
  expect(new Set(sites.map((s) => classify(s).id)).size).toBe(3);
  expect(() => scanFile("new.ts", "const newCapacity = 100n;")).toThrow("explicit ledger representation");
});
test("ledger refuses fake facts, missing provenance, unsupported Free Mode certainty and invalid units", () => {
  const entry = classify(scanFile("packages/simulation/src/test.ts", "const x = 4;")[0]!);
  expect(validateLedger([entry])).toEqual([]);
